    /**
     * Tests getting all ExternalAccounts.
     *
     * @return    Collection
     */
    public List<ExternalAccount> testGetAll() throws Throwable {
    LOGGER.info( "ExternalAccountTest:testGetAll() - Retrieving Collection of ExternalAccounts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ExternalAccount : " );
    List<ExternalAccount> collection  = null;

    try {
        // call the static get method on the ExternalAccountService
        collection = service.getAllExternalAccount();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ExternalAccount currEntity  = null;
            Iterator<ExternalAccount> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getExternalAccountId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

